# ================================================================  ۱. مقدمه
d.heading("۱. مقدمه")
d.para(f"سرمایه‌گذار حقیقی در هر لحظه با دو جریان اطلاعاتی رقیب روبه‌روست: جریان پرشتاب و هیجانی شبکه‌های اجتماعی، و جریان کندتر اما قابل‌راستی‌آزمایی گزارش‌های مالی. پژوهش‌های پیشین نشان داده‌اند توجه سرمایه‌گذاران خرد کمیاب است و خرید آن‌ها به سهامِ مورد توجه گرایش دارد {KK('barber2008','da2011')}. رسانه‌های اجتماعی هم سرعت انتشار افشا را افزایش می‌دهند {K('blankespoor2014', True)} و هم خطر هم‌جهتی و اتاق‌های پژواک را {K('cookson2023', True)}. در بازار سرمایهٔ ایران، ریزش بورس پس از مرداد ۱۳۹۹ نیز تجربهٔ زیان را برای شمار زیادی از سرمایه‌گذاران به همراه داشت؛ تجربه‌ای که می‌تواند حساسیت هیجانی آنان را نسبت به فرصت‌های از دست‌رفته تغییر دهد.")
d.para(f"این مقاله مقالهٔ همراه پژوهشی است که مسیر مواجهه ← فومو ← رفتار توده‌وار ← کیفیت تصمیم را با تعدیل‌گری اطلاعات حسابداری آزموده است. در اینجا پرسش دیگری مطرح است: چه چیزی فومو را می‌سازد، رقابت میان منابع اطلاعاتی چگونه است، آیا این روابط پس از تجربهٔ ریزش بازار تغییر می‌کند، و آیا مدل‌های غیرخطی چیزی افزون بر مدل ساختاری می‌گویند؟ در ادبیات داخلی، پژوهش‌هایی نقش سوگیری‌های رفتاری و سواد مالی در تصمیم سرمایه‌گذاران ({K('tarazoodar1402', True)})، اثر احساسات سرمایه‌گذاران بر بازده ({K('nadiri1403', True)}) و اثر رسانه‌ها و شبکه‌های اجتماعی بر تصمیمات سرمایه‌گذاران ({K('heidari1402', True)}) را بررسی کرده‌اند، اما پیش‌برنده‌های روان‌شناختی فومو و رقابت آن با اطلاعات حسابداری کمتر در یک مدل پنهان یکپارچه آزموده شده است.")
d.para("**پرسش‌های پژوهش:** (۱) مقایسهٔ اجتماعی و پشیمانی پیش‌بینی‌شده چه سهمی در فومو دارند؟ (۲) آیا مواجهه با محتوای شبکه‌ها جایگزین استفاده از اطلاعات حسابداری می‌شود و سواد حسابداری چه نقشی دارد؟ (۳) آیا ساختار اندازه‌گیری و مسیرهای مدل میان سرمایه‌گذاران دارای و فاقد تجربهٔ زیان در ریزش بورس مشابه است؟ (۴) آیا مدل‌های غیرخطی یادگیری ماشین دقت پیش‌بینی کیفیت تصمیم را بهبود می‌دهند و یافته‌هایشان با مدل ساختاری سازگار است؟")
d.para("دو ویژگی مقاله را از مقالهٔ همراه متمایز می‌کند: نخست، تمرکز بر پیش‌برنده‌های فومو و رقابت اطلاعاتی، و دوم، ترکیب مدل‌سازی معادلات ساختاری تمام‌پنهان (هر گویه مستقیماً به سازهٔ خود متصل است و میانگین‌گیری از گویه‌ها در هیچ مرحله‌ای انجام نمی‌شود) با یادگیری ماشین تفسیرپذیر که با عنوان «علوم محاسباتی» همخوان است. داده‌ها شبیه‌سازی‌شده‌اند و اعداد بازتاب توان روش در بازیابی ساختار مفروض‌اند، نه شواهد تجربی دربارهٔ بازار واقعی؛ با این همه، چارچوب، پرسشنامه و کد برای اجرای دوباره با داده‌های واقعی آماده است. ساختار مقاله: مبانی نظری و فرضیه‌ها، روش‌شناسی، یافته‌ها، و بحث و نتیجه‌گیری.")

# ================================================================  ۲. مبانی نظری
d.heading("۲. مبانی نظری و فرضیه‌ها")
d.heading("۲-۱. فومو و پیش‌برنده‌های آن", 2)
d.para(f"{T('فومو','Fear of Missing Out')} را نگرانی از آن می‌توان دانست که دیگران تجربه‌های پاداش‌آوری دارند که فرد از آن‌ها بازمانده است {K('przybylski2013', True)}. این سازه با استفادهٔ بیشتر از شبکه‌های اجتماعی همبسته است {K('abel2016', True)} و {K('milyavskaya2018')} پویایی و پیامدهای تجربهٔ آن را بررسی کرده‌اند. دو سازوکار روان‌شناختی از مهم‌ترین پیش‌برنده‌های آن در بازار سرمایه‌اند.")
d.para(f"نخست، {T('مقایسهٔ اجتماعی','Social comparison')}: افراد ارزیابی خود را از مقایسه با دیگران می‌سازند {K('festinger1954', True)} و گرایش فردی به مقایسه با دیگران قابل‌سنجش است {K('gibbons1999', True)}. شبکه‌های اجتماعی با نمایش گزینشی سودها، این مقایسه را تشدید می‌کنند و سرمایه‌گذار را در برابر «معیاری» قرار می‌دهند که از او بهتر عمل کرده است. دوم، {T('پشیمانی پیش‌بینی‌شده','Anticipated regret')}: نظریهٔ پشیمانی نشان می‌دهد افراد پیامد عاطفی نزدیک‌بودن به فرصت از دست‌رفته را پیش‌بینی می‌کنند و انتخاب‌هایشان را برای پرهیز از آن تغییر می‌دهند {KK('loomes1982','sandberg2008')}. مقیاس پشیمانی {K('schwartz2002')} نیز نشان داد تمایل به پشیمانی ویژگی قابل‌سنجش و متفاوت میان افراد است. در تصمیم‌های سرمایه‌گذاری، دو شکل پشیمانی (خریدنِ سهمی که زیان داد و نخریدنِ سهمی که رشد کرد) هر دو ممکن‌اند، اما فومو بیشتر با شکل دوم، یعنی ترس از فرصت از دست‌رفته، پیوند دارد.")
d.para("**فرضیهٔ ۱:** مقایسهٔ اجتماعی بر فومو اثر مثبت دارد.  **فرضیهٔ ۲:** پشیمانی پیش‌بینی‌شده بر فومو اثر مثبت دارد.", indent=False)
d.heading("۲-۲. رقابت منابع اطلاعاتی و سواد حسابداری", 2)
d.para(f"رقابت میان منابع اطلاعاتی بر پایهٔ محدودیت توجه است: وقت و توجه سرمایه‌گذار محدود است و اختصاص آن به یک منبع، از دیگری می‌کاهد {KK('barber2008','hirshleifer2003b')}. اطلاعات حسابداری از پایه‌های ارزش‌گذاری است {KK('ball1968','beaver1968')}، اما بهره‌گیری از آن نیازمند مهارت است؛ {K('lawrence2013')} نشان داد سرمایه‌گذاران حقیقی با افشای ساده‌تر عملکرد بهتری دارند. از سوی دیگر، شبکه‌های اجتماعی ممکن است جایگزین بررسی صورت‌های مالی شوند، زیرا هزینهٔ پردازش آن‌ها بسیار کمتر است {KK('miller2015','bartov2018')}، هرچند می‌توانند مکمل نیز باشند {K('blankespoor2014', True)}. در ایران، {K('namazi1399')} نشان داده‌اند علایق اطلاعاتی حسابداری سرمایه‌گذاران با تیپ شخصیتی آنان تغییر می‌کند و {K('bahar1397')} نشان داده‌اند کیفیت اطلاعات حسابداری شدت رفتارهای احساسی سرمایه‌گذاران را در قیمت‌گذاری کاهش می‌دهد.")
d.para(f"سواد حسابداری ادراک‌شده، که در امتداد مفهوم سواد مالی {K('lusardi2014', True)} قرار می‌گیرد، توان استفاده از افشا را تعیین می‌کند. {K('tarazoodar1402')} نیز نقش سواد مالی را در کنار تورش‌های رفتاری در تصمیم‌گیری سرمایه‌گذاران برجسته کرده‌اند. بنابراین انتظار می‌رود سرمایه‌گذارِ دارای سواد حسابداری بالاتر، بیشتر از اطلاعات حسابداری استفاده کند، و هرچه مواجهه با محتوای شبکه‌ها بیشتر باشد، سهم توجه به اطلاعات حسابداری کمتر شود (اثر جایگزینی).")
d.para("**فرضیهٔ ۳:** مواجهه با محتوای سرمایه‌گذاری شبکه‌های اجتماعی بر استفاده از اطلاعات حسابداری اثر منفی دارد.  **فرضیهٔ ۴:** سواد حسابداری بر استفاده از اطلاعات حسابداری اثر مثبت دارد.", indent=False)
d.heading("۲-۳. پیامدهای فومو و اطلاعات حسابداری", 2)
d.para(f"هیجان‌ها تصمیم را به شیوه‌ای نظام‌مند شکل می‌دهند {K('lerner2015', True)}. فومو با شتاب‌زدگی در ورود به بازار و تصمیم‌های کم‌پشتوانه همراه است و بنابراین کیفیت تصمیم را کاهش می‌دهد؛ در مقابل، استفاده از اطلاعات حسابداری پایهٔ تصمیم را مستند می‌کند و با شایستگی تصمیم‌گیری سازگار است {KK('parker2005','bruine2007')}. در ادبیات داخلی نیز ارتباط سوگیری‌های رفتاری با عملکرد سرمایه‌گذاران حقیقی گزارش شده است {K('jamshidi1398', True)}.")
d.para("**فرضیهٔ ۵:** فومو بر کیفیت تصمیم اثر منفی دارد.  **فرضیهٔ ۶:** استفاده از اطلاعات حسابداری بر کیفیت تصمیم اثر مثبت دارد.  **فرضیهٔ ۷:** مقایسهٔ اجتماعی، پشیمانی پیش‌بینی‌شده و مواجهه با محتوا از مسیر فومو، و سواد حسابداری از مسیر استفاده از اطلاعات حسابداری، اثر غیرمستقیم معنادار بر کیفیت تصمیم دارند.", indent=False)
d.heading("۲-۴. تجربهٔ زیان و تفاوت گروهی", 2)
d.para(f"ریزش بورس تهران از مرداد ۱۳۹۹ برای بسیاری از سرمایه‌گذاران تجربهٔ زیان را به همراه داشت. نظریهٔ چشم‌انداز نشان می‌دهد زیان سنگین‌تر از سود هم‌اندازه ارزیابی می‌شود {K('kahneman1979', True)} و رفتار سرمایه‌گذاران پس از زیان تغییر می‌کند {K('odean1998', True)}. بنابراین تجربهٔ زیان ممکن است حساسیت به پشیمانی و شدت پیامد فومو را افزایش دهد. پیش از مقایسهٔ مسیرها باید {T('ناوردایی اندازه‌گیری','Measurement invariance')} برقرار باشد، یعنی گویه‌ها در دو گروه یک سازه را به یک شیوه بسنجند {KK('cheung2002','chen2007')}.")
d.para("**فرضیهٔ ۸:** ساختار اندازه‌گیری (پیکربندی، متریک و دست‌کم اسکالر جزئی) میان دو گروه ناوردا است.  **فرضیهٔ ۹:** اثر پشیمانی پیش‌بینی‌شده بر فومو در گروه دارای تجربهٔ زیان قوی‌تر است.  **فرضیهٔ ۱۰:** اثر فومو بر کیفیت تصمیم در گروه دارای تجربهٔ زیان منفی‌تر است.", indent=False)
d.heading("۲-۵. غیرخطی‌بودن و یادگیری ماشین تفسیرپذیر", 2)
d.para(f"مدل‌های ساختاری روابط خطی و جمع‌پذیر را فرض می‌کنند، حال آنکه اثر فومو ممکن است آستانه‌ای باشد و اطلاعات حسابداری اثر آن را تعدیل کند. جنگل تصادفی {K('breiman2001', True)} و تقویت گرادیان {K('friedman2001', True)} این غیرخطی‌بودن را می‌گیرند و تفسیر SHAP {K('lundberg2017', True)} اهمیت متغیرها را قابل‌مقایسه با ضرایب ساختاری می‌کند. برای پرهیز از میانگین‌گیری ساده از گویه‌ها، ویژگی‌های ورودی مدل‌های یادگیری ماشین نمرات عاملی وزن‌دار مبتنی بر بارهای مدل اندازه‌گیری‌اند (روش دومرحله‌ای SEM ـ ML).")
d.para("**فرضیهٔ ۱۱:** مدل‌های غیرخطی دقت پیش‌بینی بیرون‌نمونه‌ای کیفیت تصمیم را نسبت به رگرسیون خطی افزایش می‌دهند.  **فرضیهٔ ۱۲:** رتبه‌بندی اهمیت SHAP با رتبه‌بندی اثرهای کل مدل ساختاری هم‌خوان است.", indent=False)
d.para("شکل ۱ مدل مفهومی را با همهٔ سازه‌های پنهان و گویه‌های سنجندهٔ آن‌ها نشان می‌دهد.")
