N = R["n"]; p_obs = 35; q_sem = int(p_obs*(p_obs+1)/2 - SEM["df"]); q_cfa = int(33*34/2 - CFA["df"])
def pwt(x): return 'بیش از ۰٫۹۹' if x > .995 else f2(x)
def power_rmsea(N_, df_, e0=.05, e1=.08):
    from scipy.stats import ncx2
    crit = ncx2.ppf(.95, df_, (N_-1)*df_*e0**2); return float(1 - ncx2.cdf(crit, df_, (N_-1)*df_*e1**2))
d.para(f"پژوهش کمّی، مقطعی و پیمایشی است. جامعه سرمایه‌گذاران حقیقی فعال در بورس و فرابورس تهران با حداقل یک سال سابقه است و نمونهٔ شبیه‌سازی‌شده {fa(str(N))} نفر دارد که {fa(str(G['n1']))} نفر ({F1(G['pct1'])}٪) در ریزش بورس از مرداد ۱۳۹۹ زیان بیش از ۲۰٪ سرمایه را گزارش کرده‌اند و {fa(str(G['n0']))} نفر چنین تجربه‌ای نداشته‌اند. شمار پارامترهای آزاد مدل اندازه‌گیری {fa(str(q_cfa))} و مدل ساختاری {fa(str(q_sem))} است و نسبت مشاهده به پارامتر به‌ترتیب {f2(N/q_cfa)} و {f2(N/q_sem)} می‌شود که از قاعدهٔ سرانگشتی ۱۰ به ۱ کمتر است؛ با این حال اندازهٔ نمونهٔ لازم به ساختار مدل بستگی دارد {K('wolf2013', True)} و توان آزمون برازش نزدیک در برابر برازش ضعیف {K('maccallum1996', True)} برای مدل اندازه‌گیری {pwt(power_rmsea(N, int(CFA['df'])))} و برای مدل ساختاری {pwt(power_rmsea(N, int(SEM['df'])))} است. در مقایسهٔ گروهی، اندازهٔ هر گروه (به‌ترتیب {fa(str(G['n0']))} و {fa(str(G['n1']))}) محدودیت توان بیشتری ایجاد می‌کند که در محدودیت‌ها آمده است.")
