def gs(g): 
    x = df if g is None else df[df.LE == g]
    return [F0(len(x)), F1((x.gender == 1).mean()*100) + "٪", f"{F1(x.age.mean())} ({F1(x.age.std())})", f"{F1(x.exp.mean())} ({F1(x.exp.std())})",
            F1((x.edu >= 3).mean()*100) + "٪", f"{F0(x.portfolio.median())}"]
